//! The NCEP/NCAR Reanalysis 1's monthly near-surface air temperature over 1991–2020, reduced to the
//! sea level over land at the reference Earth's lapse rate, on Earth's land boxes (R09.T13.l): the
//! observed side of the geographic model's comparison with observed climatologies
//! ([`climatology`](super::climatology)), its boxes those of [`gpcp_boxes`](super::gpcp_boxes), in
//! the same order. Test data, not shipped (`NOTICE`, "Test data (not shipped)"). The dataset's
//! citation: E. Kalnay et al. 1996, "The NCEP/NCAR 40-Year Reanalysis Project", Bull. Amer. Meteor.
//! Soc. 77, 437–471.
//!
//! # The inputs
//!
//! NOAA ARL's archive of the reanalysis, as NOAA's Open Data Dissemination programme (NODD)
//! distributes it on AWS (the bucket `noaa-oar-arl-hysplit-pds`, `reanalysis/<year>/`): the 360
//! monthly files `RP<yyyymm>.gbl` of January 1991 to December 2020, each every 6 hours on the 2.5°
//! grid of 144 × 73 points from 0° E and 90° S, in ARL's packed format. Their `sha256sum` listing
//! in name order has SHA-256 `ad7fa28ea9e398ea66c39e35ade1a4f9956770bceeda232a5e0e50389fa71b59`.
//! The archive's `README.TXT` (revised 9 July 2026) says its pressure-level data "were obtained
//! from the NOAA-CIRES Climate Diagnostics Center" and hold "Surface or near the surface (.995
//! sigma level) winds and temperature": its `T02M` is the reanalysis's σ = 0.995 air temperature,
//! about 40 m above the ground, not the 2 m air temperature of [`ncep_air`](super::ncep_air), whose
//! source (NOAA PSL's `air.2m.mon.ltm.1991-2020.nc`) could not be reached from the lane's machine
//! (plan 09's R09.T13.l record). NODD's terms: its data "are open to the public and can be used as
//! desired", NOAA requesting attribution and no implied endorsement.
//!
//! The land mask is Natural Earth's 1:110m land polygons (public domain, naturalearthdata.com,
//! "Made with Natural Earth"), the same `ne_110m_land.geojson` as
//! [`earth_land`](super::earth_land)'s, SHA-256
//! `9e0729ee253ca7d7a5c4ae9395fb1902264c5377c52e224d13dd85010e2835d9` (release 4.1.0, by the
//! history of `nvkelso/natural-earth-vector`, whose copy was read), standing in for the
//! reanalysis's own mask.
//!
//! # The method
//!
//! - Each 6-hourly time's `T02M`, K, and the reanalysis's surface height z, m, which the archive
//!   does not hold: recovered from its surface pressure `PRSS` and the pressure levels' heights
//!   `HGTS` by linear interpolation in ln p between the two levels that bracket it, and below 1000
//!   hPa by the hypsometric equation from 1000 hPa at that level's `TEMP` (R 287.05 J kg⁻¹ K⁻¹, g
//!   9.806 65 m s⁻²). Each month's means over its times, and each calendar month's over the 30
//!   years; z the mean over all 360 months (its months' spread about it 1.8 m RMS, 20.5 m at
//!   worst). Over the land boxes the boxes' mean z correlates with Earth2014's box medians
//!   ([`EARTH_BOX_MEDIAN_M`](super::EARTH_BOX_MEDIAN_M)) at 0.979, 20 m lower on average.
//! - Each point's temperature, plus Γ max(0, z) where Natural Earth's land share of its 2.5° cell
//!   (its latitude and longitude ± 1.25°, clipped at the poles; even–odd scanlines, 40 to 2.5° of
//!   latitude, each weighted by cos φ, as [`earth_land`](super::earth_land)'s) exceeds 0.5, with Γ
//!   [`REDUCTION_LAPSE_RATE_K_PER_M`](super::ncep_air::REDUCTION_LAPSE_RATE_K_PER_M), 5.829 K km⁻¹:
//!   [`ncep_air`](super::ncep_air)'s reduction (where z is negative, over the spectral orography's
//!   ringing beside the Andes, none). The σ = 0.995 level's own height above the ground, about
//!   40 m, is not added: 0.2 K.
//! - A box's value: the solid-angle mean of the points' 2.5° cells over it, its latitudes the upper
//!   half of one row's cells and the lower half of the next's, by their solid angles, and its
//!   longitudes ¼, ½ and ¼ of three columns' cells.
//! - Printed in hundredths of a kelvin (the packing's precision is 0.063 K a value).
//! - The check, against the 2 m field: the same reduction's band means over all longitudes, by the
//!   same latitude weights, against [`SEA_LEVEL_AIR_K`](super::ncep_air::SEA_LEVEL_AIR_K), from
//!   58.75° S to 58.75° N, 0.34 K RMS over the months and bands, 1.10 K at worst; to 76.25° N,
//!   0.45 K and 1.80 K; over every band, 1.02 K RMS and 5.59 K at worst, at 88.75° S in May. Those
//!   bands are mostly sea, so over land the difference may be two or three times larger. The σ =
//!   0.995 level, some 30–40 m up, stands within the polar winter's surface inversion, above its
//!   steepest lowest layer: from 63.75° S south the σ = 0.995 field is warmer by up to 5.6 K in
//!   May–August, and over the Arctic Ocean (86.25° N and 88.75° N, no land) by 1.1–1.3 K in the
//!   annual mean.
//!
//! The lane's scripts (`arl_reduce.py`, `ne_grid_land.py`, `climatology.py` and `emit_tables.py`)
//! are in its outbox, not the repository.

